  tsApprovalRemoved: ["Approval removed.", "Zatwierdzenie cofnięte.", "Aprobare anulată.", "منظوری ہٹا دی گئی۔", "ਮਨਜ਼ੂਰੀ ਹਟਾ ਦਿੱਤੀ ਗਈ।", "অনুমোদন সরানো হয়েছে।", "أُلغي الاعتماد.", "Aprovação removida.", "Aprobación retirada.", "Validation retirée.", "Tynnwyd y cymeradwyo."],
  tsHoursApproved: ["{name}’s hours approved.", "Godziny pracownika {name} zatwierdzone.", "Orele lui {name} au fost aprobate.", "{name} کے گھنٹے منظور ہو گئے۔", "{name} ਦੇ ਘੰਟੇ ਮਨਜ਼ੂਰ ਹੋ ਗਏ।", "{name}-এর ঘণ্টা অনুমোদিত হয়েছে।", "اعتُمدت ساعات {name}.", "Horas de {name} aprovadas.", "Horas de {name} aprobadas.", "Heures de {name} validées.", "Cymeradwywyd oriau {name}."],
